import { revalidateTag } from 'next/cache'
import { getProducts } from '@/lib/products'

const priceFormatter = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
})

export default async function Page() {
  const products = await getProducts()

  async function syncCatalog() {
    'use server'

    revalidateTag('products', 'max')
  }

  return (
    <main className=\"page\">
      <header className=\"topbar\">
        <div className=\"brand\"><span className=\"brand-mark\" aria-hidden=\"true\">◇</span> Commerce admin</div>
        <span className=\"topbar-section\">Catalog</span>
      </header>

      <div className=\"content\">
        <div className=\"breadcrumb\">Commerce <span aria-hidden=\"true\">/</span> Catalog</div>
        <div className=\"page-heading\">
          <div>
            <p className=\"eyebrow\">PRODUCT MANAGEMENT</p>
            <h1>Product catalog</h1>
            <p className=\"description\">Browse the products in your catalog.</p>
          </div>
          <form action={syncCatalog}>
            <button type=\"submit\"><span aria-hidden=\"true\">↻</span> Sync latest catalog</button>
          </form>
        </div>

        <div className=\"sync-note\">
          <span className=\"note-icon\" aria-hidden=\"true\">i</span>
          <p>Updated your ERP or PIM? Sync the catalog to refresh product data. Changes may take a moment to appear.</p>
        </div>

        <section className=\"catalog\" aria-labelledby=\"catalog-heading\">
          <div className=\"catalog-heading\">
            <div>
              <h2 id=\"catalog-heading\">All products <span className=\"count\">{products.length}</span></h2>
              <p>Your current catalog at a glance.</p>
            </div>
          </div>
          {products.length > 0 ? (
            <div className=\"table-wrap\">
              <table>
                <thead>
                  <tr><th scope=\"col\">Product</th><th scope=\"col\">Product ID</th><th scope=\"col\" className=\"price\">Price</th></tr>
                </thead>
                <tbody>
                  {products.map((product) => (
                    <tr key={product.id}>
                      <td><span className=\"product-name\">{product.name}</span></td>
                      <td className=\"product-id\">{product.id}</td>
                      <td className=\"price\">{priceFormatter.format(product.price)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p className=\"empty\">No products in the catalog yet.</p>
          )}
        </section>
        <p className=\"footer-note\">Showing {products.length} {products.length === 1 ? 'product' : 'products'}</p>
      </div>
    </main>
  )
}
EOF
